import{_ as e,c as t,o as r,ag as d}from"./chunks/framework.Sr95JMjc.js";const M=JSON.parse('{"title":"RangeError: Invalid Date","description":"","frontmatter":{"title":"RangeError: Invalid Date","date":"2025-08-21T22:00+09:00","tags":["Day.js","Date","Safari","RangeError","Invalid Date"]},"headers":[],"relativePath":"posts/dayjs-invalid-date.md","filePath":"posts/dayjs-invalid-date.md","lastUpdated":1779403721000}'),i={name:"posts/dayjs-invalid-date.md"};function o(Y,a,l,n,D,c){return r(),t("div",null,[...a[0]||(a[0]=[d('<h4 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h4><ul><li>Safari 브라우저는 <code>YYYY.MM.DD</code> 패턴의 문자열로 Date 객체를 생성할 수 없다.</li><li>Chrome 과 Safari 브라우저 모두 <code>YYYY-MM-DD</code> 패턴의 문자열로 Date 객체를 생성할 수 있다.</li><li>Chrome 과 Safari 브라우저 모두 <code>YYYYMMDD</code> 패턴의 문자열로 Date 객체를 생성할 수 없다.</li></ul><h4 id="rangeerror-invalid-date" tabindex="-1">RangeError: Invalid Date <a class="header-anchor" href="#rangeerror-invalid-date" aria-label="Permalink to &quot;RangeError: Invalid Date&quot;">​</a></h4><p>크롬 브라우저를 사용하는 안드로이드에서는 정상적으로 동작했던 코드가 사파리 브라우저를 사용하는 iOS 에서 <code>RangeError</code> 가 발생했다. <a href="https://developer.mozilla.org/ko/docs/Web/JavaScript/Reference/Errors/Invalid_date" target="_blank" rel="noreferrer">Invalid Date</a>는 Date 객체를 생성하려고 할때 올바르지 않은 String 이 주어진 경우의 오류를 의미한다. 최근 수정된 코드를 보니 <code>YYYY.MM.DD</code> 패턴의 문자열을 가져와서 코드 로직 상 Day.js 라이브러리에 의해 날짜 객체를 생성하고 있음을 확인할 수 있었다. 그리고 <a href="https://day.js.org/docs/en/parse/string" target="_blank" rel="noreferrer">dayjs()</a>로 객체를 생성할 때 내부적으로 자바스크립트의 Date 객체를 생성하기 때문에 오류가 발생한 것으로 보인다.</p><h4 id="safari-date-rfc822" tabindex="-1">Safari Date RFC822 <a class="header-anchor" href="#safari-date-rfc822" aria-label="Permalink to &quot;Safari Date RFC822&quot;">​</a></h4><p><img src="https://private-user-images.githubusercontent.com/17937604/480285902-a87092b7-6dc9-4978-a541-7796d2274a3d.png?jwt=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9..zqIaXubdsd1oH8XQsUjU8hJ1EOOAaXPthQrIup9t_oA" alt=""></p><p>크롬 브라우저를 사용하는 안드로이드에서는 정상적으로 동작하는 코드이기 때문에 사파리 브라우저에서 Invalid Date 가 표시되는 것에 대해 검색해보니 전통적으로 YYYY-MM-DD 패턴의 문자열인 <code>RFC822</code> 를 지원하지 않는다는 글이 대부분을 차지하고 있다. 최근에 수정되었는지 알기 어려우나 JavaScript 콘솔에서 YYYY-MM-DD 패턴으로도 Date 객체를 생성할 수 있음을 확인할 수 있었다. 기본적으로는 YYYY-MM-DD 와 <code>YYYY-MM-DD&#39;T&#39;HH:mm:ss</code> 와 같은 패턴을 주로 사용하기 때문에 사파리 브라우저에서 Date 객체를 생성하는데 문제는 없었던 것으로 보인다.</p><h4 id="yyyy-mm-dd-→-yyyy-mm-dd" tabindex="-1">YYYY.MM.DD → YYYY-MM-DD <a class="header-anchor" href="#yyyy-mm-dd-→-yyyy-mm-dd" aria-label="Permalink to &quot;YYYY.MM.DD → YYYY-MM-DD&quot;">​</a></h4><p>그러면, YYYY.MM.DD 는 왜 사용하게 되었을까를 살펴보자면 특정 이슈를 해결하기 위해 수정된 코드에서는 동일한 날짜를 표시하기 위하여 해당 변수를 가져와서 사용했고 해당 변수의 값은 YYYY.MM.DD 형태로 구성된 String 객체였던 것이다. 사실은 그 변수 자체적으로는 YYYY.MM.DD 형태로 표시되는게 맞으므로 올바르게 되어있던 부분이지만, 사파리 브라우저에서 YYYY.MM.DD 처럼 콤마로 표시된 문자열로 날짜를 생성할 때에는 불가능하기 때문에 <code>콤마를 대시로 치환해서</code> YYYY-MM-DD 형태로 사용해야한다.</p><h4 id="크로스-브라우징-이슈" tabindex="-1">크로스 브라우징 이슈 <a class="header-anchor" href="#크로스-브라우징-이슈" aria-label="Permalink to &quot;크로스 브라우징 이슈&quot;">​</a></h4><p>가끔씩 프론트엔드를 수정하다보면 크로스 브라우징 문제가 생각보다 다양함을 느낀다. 분명히 표준으로 정의되어있는 것 같지만 브라우저마다 동작이 다르다. 프론트엔드 개발자가 아니기도 하고 자바스크립트의 Date를 직접 다루지 않고 Day.js와 같은 라이브러리를 사용했기에 이러한 문제가 있을리라고는 생각하지를 못했다. 과거 프로젝트에서는 <a href="https://momentjs.com/" target="_blank" rel="noreferrer">Moment.js</a>를 사용했는데 동일한 오류를 경험해본 적은 없었던 것 같다. 여담이지만, IT 시스템 개발에서는 모든 것이 통일된다는 것을 가정할 순 없는데 시계열 데이터베이스 중에서는 <code>2025.08.21D00:00:00.000000</code> 형태로 날짜를 표현하면서 ISO 8601 포맷을 지원하지 않는 것도 있다.</p>',11)])])}const m=e(i,[["render",o]]);export{M as __pageData,m as default};
